out = {"en": {}, "de": {}}
for k,(en,de) in T.items():
    out["en"][k]=en; out["de"][k]=de
code = """// i18n de MojoBasket (generado por i18n_build.py): traduce la interfaz en vivo (es → en/de) sin tocar el HTML de la app.
// Claves = texto español con los números como {n}. Lo que no tiene traducción (nombres de tiendas, productos) se queda igual.
(function(){
var DIC=%s;
var FRAG=%s;
var LOCS={es:"es-ES",en:"en-GB",de:"de-DE"};
var K="mb_lang";
function detecta(){ try{ var g=localStorage.getItem(K); if(g&&LOCS[g]) return g; }catch(e){} var n=(navigator.language||"es").slice(0,2).toLowerCase(); return n==="en"||n==="de"?n:"es"; }
var lang=detecta();
var I={ lang:lang, loc:LOCS[lang], set:function(l){ if(!LOCS[l]) return; try{ localStorage.setItem(K,l); }catch(e){} location.reload(); }, t:t };
window.MB_I18N=I;
document.documentElement.lang=lang;
var NUM=/\\d+(?:[.,]\\d+)*/g;
function t(s){
  if(lang==="es"||!s) return s;
  var m=s.match(/^(\\s*)([\\s\\S]*?)(\\s*)$/), a=m[1], core=m[2].replace(/\\u00a0/g," "), z=m[3]; if(!core) return s;
  var d=DIC[lang], nums=[], key=core.replace(NUM,function(x){ nums.push(x); return "{n}"; });
  var v=d[core]!==undefined?d[core]:d[key]!==undefined?d[key].replace(/\\{n\\}/g,function(){ return nums.shift()||""; }):null;
  if(v===null){ var r=core, cambio=false; for(var i=0;i<FRAG.length;i++){ var f=FRAG[i], re=new RegExp(f[0]); if(re.test(r)){ r=r.replace(re,f[lang==="en"?1:2]); cambio=true; } } if(!cambio) return s; v=r; }
  return a+v+z;
}
var ATR=["placeholder","aria-label","title","alt"];
var hechos=new WeakMap();
function nodo(n){
  if(n.nodeType===3){ var p=n.parentNode; if(!p||/^(SCRIPT|STYLE|TEXTAREA)$/.test(p.nodeName)) return; if(p.closest&&p.closest("[data-no-i18n]")) return; var v=n.nodeValue; if(hechos.get(n)===v) return; var r=t(v); if(r!==v){ n.nodeValue=r; } hechos.set(n,n.nodeValue); return; }
  if(n.nodeType!==1||/^(SCRIPT|STYLE)$/.test(n.nodeName)) return;
  if(n.closest&&n.closest("[data-no-i18n]")) return;
  for(var i=0;i<ATR.length;i++){ var at=n.getAttribute&&n.getAttribute(ATR[i]); if(at){ var r=t(at); if(r!==at) n.setAttribute(ATR[i],r); } }
  for(var c=n.firstChild;c;c=c.nextSibling) nodo(c);
}
function arranca(){
  if(lang==="es") return;
  nodo(document.body);
  new MutationObserver(function(ms){ for(var i=0;i<ms.length;i++){ var m=ms[i]; if(m.type==="characterData") nodo(m.target); else if(m.type==="attributes") nodo(m.target); else for(var j=0;j<m.addedNodes.length;j++) nodo(m.addedNodes[j]); } })
    .observe(document.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:ATR});
}
if(document.readyState==="loading") document.addEventListener("DOMContentLoaded",arranca); else arranca();
})();
""" % (json.dumps(out, ensure_ascii=False), json.dumps(FRAG, ensure_ascii=False))
open(__import__('os').path.join(__import__('os').path.dirname(__file__),'..','i18n.js'),'w').write(code)
